designs.reference_rtl:
// Weight-stationary 4x4 systolic matrix multiplier, signed INT8 operands.
//
//   C[m][j] = sum over k = 0..3 of A[m][k] * W[k][j]          (m = 0..255 rows streamed, j = 0..3)
//
// The 4x4 weight tile W is loaded into the PEs at the start of a run; the 256 rows of A then stream
// through the array and one row of C leaves the bottom of the array per cycle.
//
// Organisation:
//   ws_abuf        activation buffer, 256 words of 32 bit (word m = row m of A), registered read
//   ws_wbuf        weight buffer, 4 words of 32 bit (word k = row k of W), registered read
//   ws_delay       input skew: column k of A (PE row k) is delayed by k cycles
//   ws_pe    x16   processing elements; PE(k,j) holds W[k][j], partial sums move down the column
//   ws_obank x4    output buffer, one bank per column j, 256 words of 32 bit
//   controller     weight-load phase (4 cycles), stream phase, write control of the output banks
module sa_ws_4x4 (
    input         clk,
    input         rst,
    input         a_we,
    input  [7:0]  a_addr,
    input  [31:0] a_data,
    input         w_we,
    input  [1:0]  w_addr,
    input  [31:0] w_data,
    input         start,
    output reg    done,
    input  [9:0]  c_addr,
    output [31:0] c_data
);
    localparam K = 256;                // rows streamed per run

    // ---------------------------------------------------------------- controller
    reg        busy;
    reg        wph;                    // weight-load phase (the first 4 cycles of a run)
    reg [8:0]  cnt;
    wire       go = start & ~busy;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            wph  <= 1'b0;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (go) begin
            busy <= 1'b1;
            wph  <= 1'b1;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (busy) begin
            if (wph) begin
                if (cnt == 3) begin
                    wph <= 1'b0;
                    cnt <= 9'd0;
                end else begin
                    cnt <= cnt + 9'd1;
                end
            end else begin
                cnt <= cnt + 9'd1;
                if (cnt == K + 7) begin    // the last row of C has been written to the output banks
                    busy <= 1'b0;
                    done <= 1'b1;
                end
            end
        end
    end

    // ---------------------------------------------------------------- weight load
    wire [31:0] w_rd;
    reg         wl_v;                  // w_rd holds a weight row
    reg  [1:0]  wl_r;                  // ... for this PE row

    ws_wbuf wbuf (.clk(clk), .we(w_we), .waddr(w_addr), .wdata(w_data), .raddr(cnt[1:0]), .rdata(w_rd));

    always @(posedge clk) begin
        if (rst) wl_v <= 1'b0;
        else     wl_v <= busy & wph;
        wl_r <= cnt[1:0];
    end
    wire [3:0] wl_en = {4{wl_v}} & (4'b0001 << wl_r);

    // ---------------------------------------------------------------- activation stream
    wire [31:0] a_rd;                  // byte k = A[m][k]
    ws_abuf abuf (.clk(clk), .we(a_we), .waddr(a_addr), .wdata(a_data), .raddr(cnt[7:0]), .rdata(a_rd));

    wire [7:0] a_s [0:3];
    genvar k, j;
    generate
        for (k = 0; k < 4; k = k + 1) begin : skew
            if (k == 0) begin : none
                assign a_s[k] = a_rd[8*k +: 8];
            end else begin : delayed
                ws_delay #(.W(8), .D(k)) d (.clk(clk), .din(a_rd[8*k +: 8]), .dout(a_s[k]));
            end
        end
    endgenerate

    // ---------------------------------------------------------------- PE array
    wire signed [7:0]  ah [0:19];      // a operand entering PE(k,j): index k*5+j
    wire signed [31:0] ps [0:19];      // partial sum entering PE(k,j): index k*4+j (k = 4: leaves the array)

    generate
        for (j = 0; j < 4; j = j + 1) begin : zero
            assign ps[j] = 32'sd0;
        end
        for (k = 0; k < 4; k = k + 1) begin : row
            assign ah[k*5] = a_s[k];
            for (j = 0; j < 4; j = j + 1) begin : col
                ws_pe pe (
                    .clk(clk), .ld(wl_en[k]), .w_in(w_rd[8*j +: 8]),
                    .a_in(ah[k*5+j]), .a_out(ah[k*5+j+1]),
                    .ps_in(ps[k*4+j]), .ps_out(ps[(k+1)*4+j])
                );
            end
        end
    endgenerate

    // ---------------------------------------------------------------- output banks
    // Row m of column j leaves the array in cycle m+5+j of the stream phase.
    wire       ov0 = busy & ~wph & (cnt >= 5) & (cnt < K + 5);
    reg  [2:0] ov_d;                   // ov0 delayed by 1, 2 and 3 cycles
    wire [3:0] ow  = {ov_d, ov0};      // write enable of bank j
    reg  [7:0] oc [0:3];               // write address of bank j
    integer    n;

    always @(posedge clk) begin
        ov_d <= {ov_d[1:0], ov0};
        for (n = 0; n < 4; n = n + 1) begin
            if (go)         oc[n] <= 8'd0;
            else if (ow[n]) oc[n] <= oc[n] + 8'd1;
        end
    end

    wire [31:0] c_rd [0:3];
    reg  [1:0]  csel;                  // bank selected by the read address, aligned with the read data
    always @(posedge clk) csel <= c_addr[9:8];

    generate
        for (j = 0; j < 4; j = j + 1) begin : bank
            ws_obank ob (.clk(clk), .we(ow[j]), .waddr(oc[j]), .wdata(ps[16+j]),
                         .raddr(c_addr[7:0]), .rdata(c_rd[j]));
        end
    endgenerate
    assign c_data = c_rd[csel];
endmodule


// Activation buffer: simple dual-port memory, synchronous write, registered read.
module ws_abuf (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [31:0] wdata,
    input  [7:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Weight buffer: 4 words, registered read.
module ws_wbuf (
    input         clk,
    input         we,
    input  [1:0]  waddr,
    input  [31:0] wdata,
    input  [1:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:3];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Output bank: simple dual-port memory, synchronous write, registered read.
module ws_obank (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [31:0] wdata,
    input  [7:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// D-cycle delay line of a W-bit signal (D >= 1).
module ws_delay #(parameter W = 8, parameter D = 1) (
    input          clk,
    input  [W-1:0] din,
    output [W-1:0] dout
);
    reg [W-1:0] sh [0:D-1];
    integer n;

    always @(posedge clk) begin
        sh[0] <= din;
        for (n = 1; n < D; n = n + 1) sh[n] <= sh[n-1];
    end
    assign dout = sh[D-1];
endmodule


// Processing element: keeps one weight, passes the activation on to the right and adds the
// product to the partial sum coming from above.
module ws_pe (
    input                     clk,
    input                     ld,       // loads the weight
    input  signed [7:0]       w_in,
    input  signed [7:0]       a_in,
    input  signed [31:0]      ps_in,
    output reg signed [7:0]   a_out,
    output reg signed [31:0]  ps_out
);
    reg signed [7:0] w;
    wire signed [15:0] prod = a_in * w;

    always @(posedge clk) begin
        if (ld) w <= w_in;
        a_out  <= a_in;
        ps_out <= ps_in + prod;
    end
endmodule

designs.Testbench:
`timescale 1ns/1ps

// Cycle-exact testbench of sa_ws_4x4. The design under test (uut) and an untouched copy of the reference
// (refm, modules renamed ref_*) get the same stimulus; 'done' is compared every cycle and 'c_data' while
// the result is read out. The reference is also checked against a software matrix product.
module sa_ws_4x4_tb;
    localparam K    = 256;
    localparam NOUT = 1024;
    localparam RUNS = 3;

    reg         clk;
    reg         rst, start, a_we, w_we;
    reg  [7:0]  a_addr;
    reg  [1:0]  w_addr;
    reg  [31:0] a_data, w_data;
    reg  [9:0]  c_addr;
    wire        done_d, done_r;
    wire [31:0] cd_d, cd_r;

    sa_ws_4x4 uut (.clk(clk), .rst(rst), .a_we(a_we), .a_addr(a_addr), .a_data(a_data),
                   .w_we(w_we), .w_addr(w_addr), .w_data(w_data), .start(start), .done(done_d),
                   .c_addr(c_addr), .c_data(cd_d));
    ref_sa_ws_4x4 refm (.clk(clk), .rst(rst), .a_we(a_we), .a_addr(a_addr), .a_data(a_data),
                        .w_we(w_we), .w_addr(w_addr), .w_data(w_data), .start(start), .done(done_r),
                        .c_addr(c_addr), .c_data(cd_r));

    initial clk = 0;
    always #5 clk = ~clk;

    // ---- software model: A[m*4+k], W[k*4+j], expc[j*K+m] (= c_addr) ----
    reg signed [7:0] A [0:4*K-1];
    reg signed [7:0] W [0:15];
    integer expc [0:NOUT-1];
    integer seed, run, k, m, j, a, guard, since, mism, shown, refbad, cyc;
    reg cmp_on, cmp_c;

    task gen;
        input integer mode;                       // 0, 2: random; 1: every operand -128 (largest sums)
        begin
            for (k = 0; k < 4*K; k = k + 1) A[k] = (mode == 1) ? -8'sd128 : $random(seed);
            for (k = 0; k < 16; k = k + 1)  W[k] = (mode == 1) ? -8'sd128 : $random(seed);
            for (m = 0; m < K; m = m + 1)
                for (j = 0; j < 4; j = j + 1) begin
                    expc[j*K+m] = 0;
                    for (k = 0; k < 4; k = k + 1)
                        expc[j*K+m] = expc[j*K+m] + A[m*4+k] * W[k*4+j];
                end
        end
    endtask

    // ---- cycle-by-cycle comparison of the design under test with the reference copy ----
    always @(negedge clk) if (cmp_on) begin
        cyc = cyc + 1;
        if (done_d !== done_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | done=%0d (expected %0d) | FAIL", cyc, done_d, done_r);
            end
        end
        if (cmp_c && (cd_d !== cd_r)) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | c_data=%0d (expected %0d) | FAIL", cyc, $signed(cd_d), $signed(cd_r));
            end
        end
    end

    initial begin
        seed = 32'h05A00002; mism = 0; shown = 0; refbad = 0; cyc = 0;
        cmp_on = 0; cmp_c = 0;
        rst = 1; start = 0; a_we = 0; w_we = 0; a_addr = 0; w_addr = 0; a_data = 0; w_data = 0; c_addr = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        repeat (24) @(posedge clk);
        #1 rst = 0;
        cmp_on = 1;
        for (run = 0; run < RUNS; run = run + 1) begin
            gen((run == 1) ? 1 : 0);
            // load the activation buffer (one row per cycle) and, in the first 4 cycles, the weight buffer
            for (k = 0; k < K; k = k + 1) begin
                @(posedge clk); #1;
                a_we = 1; a_addr = k; a_data = {A[k*4+3], A[k*4+2], A[k*4+1], A[k*4]};
                w_we = (k < 4); w_addr = k; w_data = {W[(k%4)*4+3], W[(k%4)*4+2], W[(k%4)*4+1], W[(k%4)*4]};
            end
            @(posedge clk); #1; a_we = 0; w_we = 0;
            repeat (3) @(posedge clk);
            #1 start = 1;
            @(posedge clk); #1 start = 0;
            // wait for done
            guard = 0; since = 0;
            while (done_d !== 1'b1 && guard < 1000) begin
                @(posedge clk); #1; guard = guard + 1; since = since + 1;
            end
            $display("run %0d: done raised %0d cycles after the start edge", run, since + 1);
            // read out: c_addr is sampled at an edge, c_data is valid right after the next edge
            cmp_c = 1;
            for (a = 0; a <= NOUT; a = a + 1) begin
                @(posedge clk); #1;
                if (a > 0 && $signed(cd_r) !== expc[a-1]) begin
                    refbad = refbad + 1;
                    if (refbad <= 5) $display(" reference check: C[addr %0d] = %0d, software model %0d", a-1, $signed(cd_r), expc[a-1]);
                end
                c_addr = (a < NOUT) ? a : 0;
            end
            cmp_c = 0;
            repeat (4) @(posedge clk);
        end
        #1;
        $display("-------------------------------------");
        $display("Compared %0d cycles", cyc);
        if (refbad != 0) $display("Reference model mismatch (%0d)", refbad);
        else if (mism == 0) $display("All tests passed");
        else $display("Some tests failed (%0d mismatching cycles)", mism);
        $display("=====================================");
        $finish;
    end
endmodule

// ---- untouched copy of the reference (modules renamed ref_*) ----
// Weight-stationary 4x4 systolic matrix multiplier, signed INT8 operands.
//
//   C[m][j] = sum over k = 0..3 of A[m][k] * W[k][j]          (m = 0..255 rows streamed, j = 0..3)
//
// The 4x4 weight tile W is loaded into the PEs at the start of a run; the 256 rows of A then stream
// through the array and one row of C leaves the bottom of the array per cycle.
//
// Organisation:
//   ref_ws_abuf        activation buffer, 256 words of 32 bit (word m = row m of A), registered read
//   ref_ws_wbuf        weight buffer, 4 words of 32 bit (word k = row k of W), registered read
//   ref_ws_delay       input skew: column k of A (PE row k) is delayed by k cycles
//   ref_ws_pe    x16   processing elements; PE(k,j) holds W[k][j], partial sums move down the column
//   ref_ws_obank x4    output buffer, one bank per column j, 256 words of 32 bit
//   controller     weight-load phase (4 cycles), stream phase, write control of the output banks
module ref_sa_ws_4x4 (
    input         clk,
    input         rst,
    input         a_we,
    input  [7:0]  a_addr,
    input  [31:0] a_data,
    input         w_we,
    input  [1:0]  w_addr,
    input  [31:0] w_data,
    input         start,
    output reg    done,
    input  [9:0]  c_addr,
    output [31:0] c_data
);
    localparam K = 256;                // rows streamed per run

    // ---------------------------------------------------------------- controller
    reg        busy;
    reg        wph;                    // weight-load phase (the first 4 cycles of a run)
    reg [8:0]  cnt;
    wire       go = start & ~busy;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            wph  <= 1'b0;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (go) begin
            busy <= 1'b1;
            wph  <= 1'b1;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (busy) begin
            if (wph) begin
                if (cnt == 3) begin
                    wph <= 1'b0;
                    cnt <= 9'd0;
                end else begin
                    cnt <= cnt + 9'd1;
                end
            end else begin
                cnt <= cnt + 9'd1;
                if (cnt == K + 7) begin    // the last row of C has been written to the output banks
                    busy <= 1'b0;
                    done <= 1'b1;
                end
            end
        end
    end

    // ---------------------------------------------------------------- weight load
    wire [31:0] w_rd;
    reg         wl_v;                  // w_rd holds a weight row
    reg  [1:0]  wl_r;                  // ... for this PE row

    ref_ws_wbuf wbuf (.clk(clk), .we(w_we), .waddr(w_addr), .wdata(w_data), .raddr(cnt[1:0]), .rdata(w_rd));

    always @(posedge clk) begin
        if (rst) wl_v <= 1'b0;
        else     wl_v <= busy & wph;
        wl_r <= cnt[1:0];
    end
    wire [3:0] wl_en = {4{wl_v}} & (4'b0001 << wl_r);

    // ---------------------------------------------------------------- activation stream
    wire [31:0] a_rd;                  // byte k = A[m][k]
    ref_ws_abuf abuf (.clk(clk), .we(a_we), .waddr(a_addr), .wdata(a_data), .raddr(cnt[7:0]), .rdata(a_rd));

    wire [7:0] a_s [0:3];
    genvar k, j;
    generate
        for (k = 0; k < 4; k = k + 1) begin : skew
            if (k == 0) begin : none
                assign a_s[k] = a_rd[8*k +: 8];
            end else begin : delayed
                ref_ws_delay #(.W(8), .D(k)) d (.clk(clk), .din(a_rd[8*k +: 8]), .dout(a_s[k]));
            end
        end
    endgenerate

    // ---------------------------------------------------------------- PE array
    wire signed [7:0]  ah [0:19];      // a operand entering PE(k,j): index k*5+j
    wire signed [31:0] ps [0:19];      // partial sum entering PE(k,j): index k*4+j (k = 4: leaves the array)

    generate
        for (j = 0; j < 4; j = j + 1) begin : zero
            assign ps[j] = 32'sd0;
        end
        for (k = 0; k < 4; k = k + 1) begin : row
            assign ah[k*5] = a_s[k];
            for (j = 0; j < 4; j = j + 1) begin : col
                ref_ws_pe pe (
                    .clk(clk), .ld(wl_en[k]), .w_in(w_rd[8*j +: 8]),
                    .a_in(ah[k*5+j]), .a_out(ah[k*5+j+1]),
                    .ps_in(ps[k*4+j]), .ps_out(ps[(k+1)*4+j])
                );
            end
        end
    endgenerate

    // ---------------------------------------------------------------- output banks
    // Row m of column j leaves the array in cycle m+5+j of the stream phase.
    wire       ov0 = busy & ~wph & (cnt >= 5) & (cnt < K + 5);
    reg  [2:0] ov_d;                   // ov0 delayed by 1, 2 and 3 cycles
    wire [3:0] ow  = {ov_d, ov0};      // write enable of bank j
    reg  [7:0] oc [0:3];               // write address of bank j
    integer    n;

    always @(posedge clk) begin
        ov_d <= {ov_d[1:0], ov0};
        for (n = 0; n < 4; n = n + 1) begin
            if (go)         oc[n] <= 8'd0;
            else if (ow[n]) oc[n] <= oc[n] + 8'd1;
        end
    end

    wire [31:0] c_rd [0:3];
    reg  [1:0]  csel;                  // bank selected by the read address, aligned with the read data
    always @(posedge clk) csel <= c_addr[9:8];

    generate
        for (j = 0; j < 4; j = j + 1) begin : bank
            ref_ws_obank ob (.clk(clk), .we(ow[j]), .waddr(oc[j]), .wdata(ps[16+j]),
                         .raddr(c_addr[7:0]), .rdata(c_rd[j]));
        end
    endgenerate
    assign c_data = c_rd[csel];
endmodule


// Activation buffer: simple dual-port memory, synchronous write, registered read.
module ref_ws_abuf (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [31:0] wdata,
    input  [7:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Weight buffer: 4 words, registered read.
module ref_ws_wbuf (
    input         clk,
    input         we,
    input  [1:0]  waddr,
    input  [31:0] wdata,
    input  [1:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:3];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Output bank: simple dual-port memory, synchronous write, registered read.
module ref_ws_obank (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [31:0] wdata,
    input  [7:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// D-cycle delay line of a W-bit signal (D >= 1).
module ref_ws_delay #(parameter W = 8, parameter D = 1) (
    input          clk,
    input  [W-1:0] din,
    output [W-1:0] dout
);
    reg [W-1:0] sh [0:D-1];
    integer n;

    always @(posedge clk) begin
        sh[0] <= din;
        for (n = 1; n < D; n = n + 1) sh[n] <= sh[n-1];
    end
    assign dout = sh[D-1];
