// Processing element: keeps one weight, passes the activation on to the right and adds the
// product to the partial sum coming from above.
module ref_ws_pe (
    input                     clk,
    input                     ld,       // loads the weight
    input  signed [7:0]       w_in,
    input  signed [7:0]       a_in,
    input  signed [31:0]      ps_in,
    output reg signed [7:0]   a_out,
    output reg signed [31:0]  ps_out
);
    reg signed [7:0] w;
    wire signed [15:0] prod = a_in * w;

    always @(posedge clk) begin
        if (ld) w <= w_in;
        a_out  <= a_in;
        ps_out <= ps_in + prod;
    end
endmodule

designs.reference_rtl:
// Input-stationary 4x4 systolic matrix multiplier, signed INT8 operands.
//
//   C[i][n] = sum over k = 0..3 of A[i][k] * B[k][n]          (i = 0..3, n = 0..255 columns streamed)
//
// The 4x4 input tile A is loaded into the PEs at the start of a run; the 256 columns of B then stream
// through the array, partial sums move along the PE rows, and one column of C is stored per cycle.
//
// Organisation:
//   is_bbuf        streamed buffer, 256 words of 32 bit (word n = column n of B), registered read
//   is_tbuf        tile buffer, 4 words of 32 bit (word i = row i of A), registered read
//   is_delay       input skew: row k of B (PE column k) is delayed by k cycles
//   is_pe    x16   processing elements; PE(i,k) holds A[i][k], partial sums move along row i
//   is_delay       output de-skew: the result of PE row i is delayed by 3-i cycles
//   is_obuf        output buffer, 256 words of 128 bit (word n = {C[3][n], C[2][n], C[1][n], C[0][n]})
//   controller     tile-load phase (4 cycles), stream phase, write control of the output buffer
module sa_is_4x4 (
    input         clk,
    input         rst,
    input         b_we,
    input  [7:0]  b_addr,
    input  [31:0] b_data,
    input         t_we,
    input  [1:0]  t_addr,
    input  [31:0] t_data,
    input         start,
    output reg    done,
    input  [9:0]  c_addr,
    output [31:0] c_data
);
    localparam K = 256;                // columns streamed per run

    // ---------------------------------------------------------------- controller
    reg        busy;
    reg        tph;                    // tile-load phase (the first 4 cycles of a run)
    reg [8:0]  cnt;
    wire       go = start & ~busy;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            tph  <= 1'b0;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (go) begin
            busy <= 1'b1;
            tph  <= 1'b1;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (busy) begin
            if (tph) begin
                if (cnt == 3) begin
                    tph <= 1'b0;
                    cnt <= 9'd0;
                end else begin
                    cnt <= cnt + 9'd1;
                end
            end else begin
                cnt <= cnt + 9'd1;
                if (cnt == K + 7) begin    // the last column of C has been written to the output buffer
                    busy <= 1'b0;
                    done <= 1'b1;
                end
            end
        end
    end

    // ---------------------------------------------------------------- tile load
    wire [31:0] t_rd;
    reg         tl_v;                  // t_rd holds a tile row
    reg  [1:0]  tl_r;                  // ... for this PE row

    is_tbuf tbuf (.clk(clk), .we(t_we), .waddr(t_addr), .wdata(t_data), .raddr(cnt[1:0]), .rdata(t_rd));

    always @(posedge clk) begin
        if (rst) tl_v <= 1'b0;
        else     tl_v <= busy & tph;
        tl_r <= cnt[1:0];
    end
    wire [3:0] tl_en = {4{tl_v}} & (4'b0001 << tl_r);

    // ---------------------------------------------------------------- B stream
    wire [31:0] b_rd;                  // byte k = B[k][n]
    is_bbuf bbuf (.clk(clk), .we(b_we), .waddr(b_addr), .wdata(b_data), .raddr(cnt[7:0]), .rdata(b_rd));

    wire [7:0] b_s [0:3];
    genvar i, k;
    generate
        for (k = 0; k < 4; k = k + 1) begin : skew
            if (k == 0) begin : none
                assign b_s[k] = b_rd[8*k +: 8];
            end else begin : delayed
                is_delay #(.W(8), .D(k)) d (.clk(clk), .din(b_rd[8*k +: 8]), .dout(b_s[k]));
            end
        end
    endgenerate

    // ---------------------------------------------------------------- PE array
    wire signed [7:0]  bv [0:19];      // b operand entering PE(i,k): index i*4+k (i = 4: leaves the array)
    wire signed [31:0] ps [0:19];      // partial sum entering PE(i,k): index i*5+k (k = 4: leaves the array)

    generate
        for (k = 0; k < 4; k = k + 1) begin : feed
            assign bv[k] = b_s[k];
        end
        for (i = 0; i < 4; i = i + 1) begin : row
            assign ps[i*5] = 32'sd0;
            for (k = 0; k < 4; k = k + 1) begin : col
                is_pe pe (
                    .clk(clk), .ld(tl_en[i]), .s_in(t_rd[8*k +: 8]),
                    .b_in(bv[i*4+k]), .b_out(bv[(i+1)*4+k]),
                    .ps_in(ps[i*5+k]), .ps_out(ps[i*5+k+1])
                );
            end
        end
    endgenerate

    // ---------------------------------------------------------------- output de-skew and buffer
    // C[i][n] leaves PE row i in cycle n+5+i of the stream phase; delaying row i by 3-i cycles
    // aligns the four values of a column in cycle n+8.
    wire [31:0] c_s [0:3];
    generate
        for (i = 0; i < 4; i = i + 1) begin : deskew
            if (i == 3) begin : none
                assign c_s[i] = ps[i*5+4];
            end else begin : delayed
                is_delay #(.W(32), .D(3-i)) d (.clk(clk), .din(ps[i*5+4]), .dout(c_s[i]));
            end
        end
    endgenerate

    wire       ow = busy & ~tph & (cnt >= 8) & (cnt < K + 8);
    reg  [7:0] oc;                     // write address of the output buffer
    always @(posedge clk) begin
        if (go)      oc <= 8'd0;
        else if (ow) oc <= oc + 8'd1;
    end

    wire [127:0] c_rd;
    reg  [1:0]   lane;                 // 32-bit lane selected by the read address, aligned with the read data
    always @(posedge clk) lane <= c_addr[1:0];

    is_obuf obuf (.clk(clk), .we(ow), .waddr(oc), .wdata({c_s[3], c_s[2], c_s[1], c_s[0]}),
                  .raddr(c_addr[9:2]), .rdata(c_rd));
    assign c_data = c_rd[32*lane +: 32];
endmodule


// Streamed buffer: simple dual-port memory, synchronous write, registered read.
module is_bbuf (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [31:0] wdata,
    input  [7:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Tile buffer: 4 words, registered read.
module is_tbuf (
    input         clk,
    input         we,
    input  [1:0]  waddr,
    input  [31:0] wdata,
    input  [1:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:3];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Output buffer: simple dual-port memory with 128-bit words, synchronous write, registered read.
module is_obuf (
    input          clk,
    input          we,
    input  [7:0]   waddr,
    input  [127:0] wdata,
    input  [7:0]   raddr,
    output reg [127:0] rdata
);
    reg [127:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// D-cycle delay line of a W-bit signal (D >= 1).
module is_delay #(parameter W = 8, parameter D = 1) (
    input          clk,
    input  [W-1:0] din,
    output [W-1:0] dout
);
    reg [W-1:0] sh [0:D-1];
    integer n;

    always @(posedge clk) begin
        sh[0] <= din;
        for (n = 1; n < D; n = n + 1) sh[n] <= sh[n-1];
    end
    assign dout = sh[D-1];
endmodule


// Processing element: keeps one input value, passes the streamed operand on downwards and adds the
// product to the partial sum coming from the left.
module is_pe (
    input                     clk,
    input                     ld,       // loads the stationary input value
    input  signed [7:0]       s_in,
    input  signed [7:0]       b_in,
    input  signed [31:0]      ps_in,
    output reg signed [7:0]   b_out,
    output reg signed [31:0]  ps_out
);
    reg signed [7:0] s;
    wire signed [15:0] prod = b_in * s;

    always @(posedge clk) begin
        if (ld) s <= s_in;
        b_out  <= b_in;
        ps_out <= ps_in + prod;
    end
endmodule

designs.Testbench:
`timescale 1ns/1ps

// Cycle-exact testbench of sa_is_4x4. The design under test (uut) and an untouched copy of the reference
// (refm, modules renamed ref_*) get the same stimulus; 'done' is compared every cycle and 'c_data' while
// the result is read out. The reference is also checked against a software matrix product.
module sa_is_4x4_tb;
    localparam K    = 256;
    localparam NOUT = 1024;
    localparam RUNS = 3;

    reg         clk;
    reg         rst, start, b_we, t_we;
    reg  [7:0]  b_addr;
    reg  [1:0]  t_addr;
    reg  [31:0] b_data, t_data;
    reg  [9:0]  c_addr;
    wire        done_d, done_r;
    wire [31:0] cd_d, cd_r;

    sa_is_4x4 uut (.clk(clk), .rst(rst), .b_we(b_we), .b_addr(b_addr), .b_data(b_data),
                   .t_we(t_we), .t_addr(t_addr), .t_data(t_data), .start(start), .done(done_d),
                   .c_addr(c_addr), .c_data(cd_d));
    ref_sa_is_4x4 refm (.clk(clk), .rst(rst), .b_we(b_we), .b_addr(b_addr), .b_data(b_data),
                        .t_we(t_we), .t_addr(t_addr), .t_data(t_data), .start(start), .done(done_r),
                        .c_addr(c_addr), .c_data(cd_r));

    initial clk = 0;
    always #5 clk = ~clk;

    // ---- software model: At[i*4+k] = A[i][k], Bs[n*4+k] = B[k][n], expc[n*4+i] (= c_addr) ----
    reg signed [7:0] At [0:15];
    reg signed [7:0] Bs [0:4*K-1];
    integer expc [0:NOUT-1];
    integer seed, run, k, n, i, a, guard, since, mism, shown, refbad, cyc;
    reg cmp_on, cmp_c;

    task gen;
        input integer mode;                       // 0, 2: random; 1: every operand -128 (largest sums)
        begin
            for (k = 0; k < 16; k = k + 1)  At[k] = (mode == 1) ? -8'sd128 : $random(seed);
            for (k = 0; k < 4*K; k = k + 1) Bs[k] = (mode == 1) ? -8'sd128 : $random(seed);
            for (n = 0; n < K; n = n + 1)
                for (i = 0; i < 4; i = i + 1) begin
                    expc[n*4+i] = 0;
                    for (k = 0; k < 4; k = k + 1)
                        expc[n*4+i] = expc[n*4+i] + At[i*4+k] * Bs[n*4+k];
                end
        end
    endtask

    // ---- cycle-by-cycle comparison of the design under test with the reference copy ----
    always @(negedge clk) if (cmp_on) begin
        cyc = cyc + 1;
        if (done_d !== done_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | done=%0d (expected %0d) | FAIL", cyc, done_d, done_r);
            end
        end
        if (cmp_c && (cd_d !== cd_r)) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | c_data=%0d (expected %0d) | FAIL", cyc, $signed(cd_d), $signed(cd_r));
            end
        end
    end

    initial begin
        seed = 32'h05A00003; mism = 0; shown = 0; refbad = 0; cyc = 0;
        cmp_on = 0; cmp_c = 0;
        rst = 1; start = 0; b_we = 0; t_we = 0; b_addr = 0; t_addr = 0; b_data = 0; t_data = 0; c_addr = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        repeat (24) @(posedge clk);
        #1 rst = 0;
        cmp_on = 1;
        for (run = 0; run < RUNS; run = run + 1) begin
            gen((run == 1) ? 1 : 0);
            // load the streamed buffer (one column per cycle) and, in the first 4 cycles, the tile buffer
            for (k = 0; k < K; k = k + 1) begin
                @(posedge clk); #1;
                b_we = 1; b_addr = k; b_data = {Bs[k*4+3], Bs[k*4+2], Bs[k*4+1], Bs[k*4]};
                t_we = (k < 4); t_addr = k; t_data = {At[(k%4)*4+3], At[(k%4)*4+2], At[(k%4)*4+1], At[(k%4)*4]};
            end
            @(posedge clk); #1; b_we = 0; t_we = 0;
            repeat (3) @(posedge clk);
            #1 start = 1;
            @(posedge clk); #1 start = 0;
            // wait for done
            guard = 0; since = 0;
            while (done_d !== 1'b1 && guard < 1000) begin
                @(posedge clk); #1; guard = guard + 1; since = since + 1;
            end
            $display("run %0d: done raised %0d cycles after the start edge", run, since + 1);
            // read out: c_addr is sampled at an edge, c_data is valid right after the next edge
            cmp_c = 1;
            for (a = 0; a <= NOUT; a = a + 1) begin
                @(posedge clk); #1;
                if (a > 0 && $signed(cd_r) !== expc[a-1]) begin
                    refbad = refbad + 1;
                    if (refbad <= 5) $display(" reference check: C[addr %0d] = %0d, software model %0d", a-1, $signed(cd_r), expc[a-1]);
                end
                c_addr = (a < NOUT) ? a : 0;
            end
            cmp_c = 0;
            repeat (4) @(posedge clk);
        end
        #1;
        $display("-------------------------------------");
        $display("Compared %0d cycles", cyc);
        if (refbad != 0) $display("Reference model mismatch (%0d)", refbad);
        else if (mism == 0) $display("All tests passed");
        else $display("Some tests failed (%0d mismatching cycles)", mism);
        $display("=====================================");
        $finish;
    end
endmodule

// ---- untouched copy of the reference (modules renamed ref_*) ----
// Input-stationary 4x4 systolic matrix multiplier, signed INT8 operands.
//
//   C[i][n] = sum over k = 0..3 of A[i][k] * B[k][n]          (i = 0..3, n = 0..255 columns streamed)
//
// The 4x4 input tile A is loaded into the PEs at the start of a run; the 256 columns of B then stream
// through the array, partial sums move along the PE rows, and one column of C is stored per cycle.
//
// Organisation:
//   ref_is_bbuf        streamed buffer, 256 words of 32 bit (word n = column n of B), registered read
//   ref_is_tbuf        tile buffer, 4 words of 32 bit (word i = row i of A), registered read
//   ref_is_delay       input skew: row k of B (PE column k) is delayed by k cycles
//   ref_is_pe    x16   processing elements; PE(i,k) holds A[i][k], partial sums move along row i
//   ref_is_delay       output de-skew: the result of PE row i is delayed by 3-i cycles
//   ref_is_obuf        output buffer, 256 words of 128 bit (word n = {C[3][n], C[2][n], C[1][n], C[0][n]})
//   controller     tile-load phase (4 cycles), stream phase, write control of the output buffer
module ref_sa_is_4x4 (
    input         clk,
    input         rst,
    input         b_we,
    input  [7:0]  b_addr,
    input  [31:0] b_data,
    input         t_we,
    input  [1:0]  t_addr,
    input  [31:0] t_data,
    input         start,
    output reg    done,
    input  [9:0]  c_addr,
    output [31:0] c_data
);
    localparam K = 256;                // columns streamed per run

    // ---------------------------------------------------------------- controller
    reg        busy;
    reg        tph;                    // tile-load phase (the first 4 cycles of a run)
    reg [8:0]  cnt;
    wire       go = start & ~busy;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            tph  <= 1'b0;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (go) begin
            busy <= 1'b1;
            tph  <= 1'b1;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (busy) begin
            if (tph) begin
                if (cnt == 3) begin
                    tph <= 1'b0;
                    cnt <= 9'd0;
                end else begin
                    cnt <= cnt + 9'd1;
                end
            end else begin
                cnt <= cnt + 9'd1;
                if (cnt == K + 7) begin    // the last column of C has been written to the output buffer
                    busy <= 1'b0;
                    done <= 1'b1;
                end
            end
        end
    end

    // ---------------------------------------------------------------- tile load
    wire [31:0] t_rd;
    reg         tl_v;                  // t_rd holds a tile row
    reg  [1:0]  tl_r;                  // ... for this PE row

    ref_is_tbuf tbuf (.clk(clk), .we(t_we), .waddr(t_addr), .wdata(t_data), .raddr(cnt[1:0]), .rdata(t_rd));

    always @(posedge clk) begin
        if (rst) tl_v <= 1'b0;
        else     tl_v <= busy & tph;
        tl_r <= cnt[1:0];
    end
    wire [3:0] tl_en = {4{tl_v}} & (4'b0001 << tl_r);

    // ---------------------------------------------------------------- B stream
    wire [31:0] b_rd;                  // byte k = B[k][n]
    ref_is_bbuf bbuf (.clk(clk), .we(b_we), .waddr(b_addr), .wdata(b_data), .raddr(cnt[7:0]), .rdata(b_rd));

    wire [7:0] b_s [0:3];
    genvar i, k;
    generate
        for (k = 0; k < 4; k = k + 1) begin : skew
            if (k == 0) begin : none
                assign b_s[k] = b_rd[8*k +: 8];
            end else begin : delayed
                ref_is_delay #(.W(8), .D(k)) d (.clk(clk), .din(b_rd[8*k +: 8]), .dout(b_s[k]));
            end
        end
    endgenerate

    // ---------------------------------------------------------------- PE array
    wire signed [7:0]  bv [0:19];      // b operand entering PE(i,k): index i*4+k (i = 4: leaves the array)
    wire signed [31:0] ps [0:19];      // partial sum entering PE(i,k): index i*5+k (k = 4: leaves the array)

    generate
        for (k = 0; k < 4; k = k + 1) begin : feed
            assign bv[k] = b_s[k];
        end
        for (i = 0; i < 4; i = i + 1) begin : row
            assign ps[i*5] = 32'sd0;
            for (k = 0; k < 4; k = k + 1) begin : col
                ref_is_pe pe (
                    .clk(clk), .ld(tl_en[i]), .s_in(t_rd[8*k +: 8]),
                    .b_in(bv[i*4+k]), .b_out(bv[(i+1)*4+k]),
                    .ps_in(ps[i*5+k]), .ps_out(ps[i*5+k+1])
                );
            end
        end
    endgenerate

    // ---------------------------------------------------------------- output de-skew and buffer
    // C[i][n] leaves PE row i in cycle n+5+i of the stream phase; delaying row i by 3-i cycles
    // aligns the four values of a column in cycle n+8.
    wire [31:0] c_s [0:3];
    generate
        for (i = 0; i < 4; i = i + 1) begin : deskew
            if (i == 3) begin : none
                assign c_s[i] = ps[i*5+4];
            end else begin : delayed
                ref_is_delay #(.W(32), .D(3-i)) d (.clk(clk), .din(ps[i*5+4]), .dout(c_s[i]));
            end
        end
    endgenerate

    wire       ow = busy & ~tph & (cnt >= 8) & (cnt < K + 8);
    reg  [7:0] oc;                     // write address of the output buffer
    always @(posedge clk) begin
        if (go)      oc <= 8'd0;
        else if (ow) oc <= oc + 8'd1;
    end

    wire [127:0] c_rd;
    reg  [1:0]   lane;                 // 32-bit lane selected by the read address, aligned with the read data
    always @(posedge clk) lane <= c_addr[1:0];

    ref_is_obuf obuf (.clk(clk), .we(ow), .waddr(oc), .wdata({c_s[3], c_s[2], c_s[1], c_s[0]}),
                  .raddr(c_addr[9:2]), .rdata(c_rd));
    assign c_data = c_rd[32*lane +: 32];
endmodule


// Streamed buffer: simple dual-port memory, synchronous write, registered read.
module ref_is_bbuf (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [31:0] wdata,
    input  [7:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Tile buffer: 4 words, registered read.
module ref_is_tbuf (
    input         clk,
    input         we,
    input  [1:0]  waddr,
    input  [31:0] wdata,
    input  [1:0]  raddr,
    output reg [31:0] rdata
);
    reg [31:0] mem [0:3];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Output buffer: simple dual-port memory with 128-bit words, synchronous write, registered read.
module ref_is_obuf (
    input          clk,
    input          we,
    input  [7:0]   waddr,
    input  [127:0] wdata,
    input  [7:0]   raddr,
    output reg [127:0] rdata
);
    reg [127:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// D-cycle delay line of a W-bit signal (D >= 1).
module ref_is_delay #(parameter W = 8, parameter D = 1) (
    input          clk,
    input  [W-1:0] din,
    output [W-1:0] dout
);
    reg [W-1:0] sh [0:D-1];
    integer n;

    always @(posedge clk) begin
        sh[0] <= din;
        for (n = 1; n < D; n = n + 1) sh[n] <= sh[n-1];
    end
    assign dout = sh[D-1];
endmodule


// Processing element: keeps one input value, passes the streamed operand on downwards and adds the
// product to the partial sum coming from the left.
module ref_is_pe (
    input                     clk,
    input                     ld,       // loads the stationary input value
    input  signed [7:0]       s_in,
    input  signed [7:0]       b_in,
    input  signed [31:0]      ps_in,
    output reg signed [7:0]   b_out,
    output reg signed [31:0]  ps_out
);
    reg signed [7:0] s;
    wire signed [15:0] prod = b_in * s;

    always @(posedge clk) begin
        if (ld) s <= s_in;
        b_out  <= b_in;
        ps_out <= ps_in + prod;
    end
endmodule

designs.reference_rtl:
// Symmetric 16-tap FIR filter on a stream of signed INT8 samples.
//
//   y[n] = sum over k = 0..15 of c[k] * x[n-k]          (c[k] = c[15-k], signed INT8 constants)
//
// Organisation:
//   fir_window   16-sample delay line; it shifts only when a sample is valid
//   fir_tree     16 constant multipliers and a 4-level adder tree, one register per level
//   fir_ctrl     valid pipeline that matches the latency of fir_tree
//   fir16        top module
module fir16 (
    input         clk,
    input         rst,
    input         x_valid,
    input  [7:0]  x_data,
    output        y_valid,
    output [23:0] y_data
);
    wire [127:0] win;                  // win[8*k +: 8] = x[n-k]

    fir_window u_win  (.clk(clk), .rst(rst), .en(x_valid), .din(x_data), .win(win));
    fir_tree   u_tree (.clk(clk), .win(win), .y(y_data));
    fir_ctrl   u_ctrl (.clk(clk), .rst(rst), .x_valid(x_valid), .y_valid(y_valid));
endmodule


// Delay line of the last 16 valid samples. A reset clears it, so a stream starts with zeros in the window.
module fir_window (
    input          clk,
    input          rst,
    input          en,
    input  [7:0]   din,
    output [127:0] win
);
    reg [7:0] sh [0:15];
    integer n;

    always @(posedge clk) begin
        if (rst) begin
            for (n = 0; n < 16; n = n + 1) sh[n] <= 8'd0;
        end else if (en) begin
            sh[0] <= din;
            for (n = 1; n < 16; n = n + 1) sh[n] <= sh[n-1];
        end
    end

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : tap
            assign win[8*g +: 8] = sh[g];
        end
    endgenerate
endmodule


// Products and adder tree. Free running: the window is read every cycle.
//   edge 1: 16 products   edge 2: 8 sums   edge 3: 4 sums   edge 4: 2 sums   edge 5: result
module fir_tree (
    input          clk,
    input  [127:0] win,
    output reg [23:0] y
);
    wire signed [7:0] c [0:15];
    assign c[0]  =  8'sd3;
    assign c[1]  = -8'sd7;
    assign c[2]  =  8'sd12;
    assign c[3]  =  8'sd25;
    assign c[4]  = -8'sd40;
    assign c[5]  =  8'sd63;
    assign c[6]  =  8'sd90;
    assign c[7]  =  8'sd118;
    assign c[8]  =  8'sd118;
    assign c[9]  =  8'sd90;
    assign c[10] =  8'sd63;
    assign c[11] = -8'sd40;
    assign c[12] =  8'sd25;
    assign c[13] =  8'sd12;
    assign c[14] = -8'sd7;
    assign c[15] =  8'sd3;

    reg signed [15:0] p  [0:15];
    reg signed [16:0] s1 [0:7];
    reg signed [17:0] s2 [0:3];
    reg signed [18:0] s3 [0:1];
    integer n;

    always @(posedge clk) begin
        for (n = 0; n < 16; n = n + 1) p[n]  <= $signed(win[8*n +: 8]) * c[n];
        for (n = 0; n < 8;  n = n + 1) s1[n] <= p[2*n] + p[2*n+1];
        for (n = 0; n < 4;  n = n + 1) s2[n] <= s1[2*n] + s1[2*n+1];
        s3[0] <= s2[0] + s2[1];
        s3[1] <= s2[2] + s2[3];
        y     <= s3[0] + s3[1];
    end
endmodule


// y_valid is x_valid delayed by the 5 register stages of fir_tree + window (v[0] is the window stage).
module fir_ctrl (
    input      clk,
    input      rst,
    input      x_valid,
    output reg y_valid
);
    reg [4:0] v;

    always @(posedge clk) begin
        if (rst) begin
            v       <= 5'd0;
            y_valid <= 1'b0;
        end else begin
            v       <= {v[3:0], x_valid};
            y_valid <= v[4];
        end
    end
endmodule

designs.Testbench:
`timescale 1ns/1ps

// Cycle-exact testbench of fir16. The design under test (uut) and an untouched copy of the reference
// (refm, modules renamed ref_*) get the same stimulus; y_valid is compared every cycle and y_data in every
// cycle where the reference raises y_valid. The reference is also checked against a software FIR model.
// Runs: 0 random samples with gaps, 1 a dense stream of -128 (largest sums), 2 random samples with gaps.
// The design is reset before every run (the window starts with zeros).
module fir16_tb;
    localparam NS   = 400;                    // clock cycles of stimulus per run
    localparam RUNS = 3;

    reg         clk, rst, x_valid;
    reg  [7:0]  x_data;
    wire        yv_d, yv_r;
    wire [23:0] yd_d, yd_r;

    fir16     uut  (.clk(clk), .rst(rst), .x_valid(x_valid), .x_data(x_data), .y_valid(yv_d), .y_data(yd_d));
    ref_fir16 refm (.clk(clk), .rst(rst), .x_valid(x_valid), .x_data(x_data), .y_valid(yv_r), .y_data(yd_r));

    initial clk = 0;
    always #5 clk = ~clk;

    // ---- software model: coefficients, window of the last 16 samples, queue of expected results ----
    reg signed [7:0] coefs [0:15];
    reg signed [7:0] hist  [0:15];
    integer expq [0:511];
    integer qw, qr;
    integer seed, run, s, cyc, mism, shown, refbad, nvalid;
    reg cmp_on, send;
    reg signed [7:0] d;

    // One accepted sample: shift the window and queue the expected output.
    task push;
        input signed [7:0] sample;
        integer t_i, t_acc;
        begin
            for (t_i = 15; t_i > 0; t_i = t_i - 1) hist[t_i] = hist[t_i-1];
            hist[0] = sample;
            t_acc = 0;
            for (t_i = 0; t_i < 16; t_i = t_i + 1) t_acc = t_acc + hist[t_i] * coefs[t_i];
            expq[qw] = t_acc;
            qw = qw + 1;
        end
    endtask

    // ---- cycle-by-cycle comparison of the design under test with the reference copy ----
    always @(negedge clk) if (cmp_on) begin
        cyc = cyc + 1;
        if (yv_d !== yv_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | y_valid=%0d (expected %0d) | FAIL", cyc, yv_d, yv_r);
            end
        end else if (yv_r === 1'b1) begin
            nvalid = nvalid + 1;
            if (yd_d !== yd_r) begin
                mism = mism + 1;
                if (shown < 20) begin
                    shown = shown + 1;
                    $display(" cycle=%0d | y_data=%0d (expected %0d) | FAIL", cyc, $signed(yd_d), $signed(yd_r));
                end
            end
            if ($signed(yd_r) !== expq[qr]) begin
                refbad = refbad + 1;
                if (refbad <= 5) $display(" reference check: y=%0d, software model %0d", $signed(yd_r), expq[qr]);
            end
            qr = qr + 1;
        end
    end

    initial begin
        coefs[0]  =  8'sd3;   coefs[1]  = -8'sd7;   coefs[2]  =  8'sd12;  coefs[3]  =  8'sd25;
        coefs[4]  = -8'sd40;  coefs[5]  =  8'sd63;  coefs[6]  =  8'sd90;  coefs[7]  =  8'sd118;
        coefs[8]  =  8'sd118; coefs[9]  =  8'sd90;  coefs[10] =  8'sd63;  coefs[11] = -8'sd40;
        coefs[12] =  8'sd25;  coefs[13] =  8'sd12;  coefs[14] = -8'sd7;   coefs[15] =  8'sd3;
        seed = 32'h0F1A0001; mism = 0; shown = 0; refbad = 0; cyc = 0; nvalid = 0; qw = 0; qr = 0;
        cmp_on = 0; rst = 1; x_valid = 0; x_data = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        repeat (24) @(posedge clk);
        #1 rst = 0;
        cmp_on = 1;
        for (run = 0; run < RUNS; run = run + 1) begin
            // reset the design and the model
            @(posedge clk); #1 rst = 1; x_valid = 0; x_data = 0;
            repeat (4) @(posedge clk);
            #1 rst = 0;
            for (s = 0; s < 16; s = s + 1) hist[s] = 0;
            qw = 0; qr = 0;
            for (s = 0; s < NS; s = s + 1) begin
                @(posedge clk); #1;
                send = (run == 1) || (($random(seed) & 3) != 0);
                if (send) begin
                    d = (run == 1) ? -8'sd128 : $random(seed);
                    x_valid = 1; x_data = d;
                    push(d);
                end else begin
                    x_valid = 0;
                end
            end
            @(posedge clk); #1 x_valid = 0;
            repeat (12) @(posedge clk);
            if (qr != qw) begin
                refbad = refbad + 1;
                $display(" run %0d: %0d outputs expected, %0d seen", run, qw, qr);
            end
            $display("run %0d: %0d samples", run, qw);
