        $finish;
    end
endmodule

// ---- untouched copy of the reference (modules renamed ref_*) ----
// Symmetric 16-tap FIR filter on a stream of signed INT8 samples.
//
//   y[n] = sum over k = 0..15 of c[k] * x[n-k]          (c[k] = c[15-k], signed INT8 constants)
//
// Organisation:
//   ref_fir_window   16-sample delay line; it shifts only when a sample is valid
//   ref_fir_tree     16 constant multipliers and a 4-level adder tree, one register per level
//   ref_fir_ctrl     valid pipeline that matches the latency of ref_fir_tree
//   ref_fir16        top module
module ref_fir16 (
    input         clk,
    input         rst,
    input         x_valid,
    input  [7:0]  x_data,
    output        y_valid,
    output [23:0] y_data
);
    wire [127:0] win;                  // win[8*k +: 8] = x[n-k]

    ref_fir_window u_win  (.clk(clk), .rst(rst), .en(x_valid), .din(x_data), .win(win));
    ref_fir_tree   u_tree (.clk(clk), .win(win), .y(y_data));
    ref_fir_ctrl   u_ctrl (.clk(clk), .rst(rst), .x_valid(x_valid), .y_valid(y_valid));
endmodule


// Delay line of the last 16 valid samples. A reset clears it, so a stream starts with zeros in the window.
module ref_fir_window (
    input          clk,
    input          rst,
    input          en,
    input  [7:0]   din,
    output [127:0] win
);
    reg [7:0] sh [0:15];
    integer n;

    always @(posedge clk) begin
        if (rst) begin
            for (n = 0; n < 16; n = n + 1) sh[n] <= 8'd0;
        end else if (en) begin
            sh[0] <= din;
            for (n = 1; n < 16; n = n + 1) sh[n] <= sh[n-1];
        end
    end

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : tap
            assign win[8*g +: 8] = sh[g];
        end
    endgenerate
endmodule


// Products and adder tree. Free running: the window is read every cycle.
//   edge 1: 16 products   edge 2: 8 sums   edge 3: 4 sums   edge 4: 2 sums   edge 5: result
module ref_fir_tree (
    input          clk,
    input  [127:0] win,
    output reg [23:0] y
);
    wire signed [7:0] c [0:15];
    assign c[0]  =  8'sd3;
    assign c[1]  = -8'sd7;
    assign c[2]  =  8'sd12;
    assign c[3]  =  8'sd25;
    assign c[4]  = -8'sd40;
    assign c[5]  =  8'sd63;
    assign c[6]  =  8'sd90;
    assign c[7]  =  8'sd118;
    assign c[8]  =  8'sd118;
    assign c[9]  =  8'sd90;
    assign c[10] =  8'sd63;
    assign c[11] = -8'sd40;
    assign c[12] =  8'sd25;
    assign c[13] =  8'sd12;
    assign c[14] = -8'sd7;
    assign c[15] =  8'sd3;

    reg signed [15:0] p  [0:15];
    reg signed [16:0] s1 [0:7];
    reg signed [17:0] s2 [0:3];
    reg signed [18:0] s3 [0:1];
    integer n;

    always @(posedge clk) begin
        for (n = 0; n < 16; n = n + 1) p[n]  <= $signed(win[8*n +: 8]) * c[n];
        for (n = 0; n < 8;  n = n + 1) s1[n] <= p[2*n] + p[2*n+1];
        for (n = 0; n < 4;  n = n + 1) s2[n] <= s1[2*n] + s1[2*n+1];
        s3[0] <= s2[0] + s2[1];
        s3[1] <= s2[2] + s2[3];
        y     <= s3[0] + s3[1];
    end
endmodule


// y_valid is x_valid delayed by the 5 register stages of ref_fir_tree + window (v[0] is the window stage).
module ref_fir_ctrl (
    input      clk,
    input      rst,
    input      x_valid,
    output reg y_valid
);
    reg [4:0] v;

    always @(posedge clk) begin
        if (rst) begin
            v       <= 5'd0;
            y_valid <= 1'b0;
        end else begin
            v       <= {v[3:0], x_valid};
            y_valid <= v[4];
        end
    end
endmodule

designs.reference_rtl:
// 3x3 convolution of a pixel stream (unsigned INT8 pixels, 64 pixels per row, signed INT8 kernel).
//
//   y(r, c) = sum over dr, dc = 0..2 of  kernel[dc*3 + dr] * pixel(r - dr, c - dc)      (r >= 2, c >= 2)
//
// Pixels arrive row by row. A frame starts after a reset; outputs are produced for every pixel that completes a
// full 3x3 window (row >= 2 and column >= 2 of the frame).
//
// Organisation:
//   conv_lbuf    line buffer: 64 words, each holds the pixels of the previous two rows at one column
//   conv_window  3x3 window of shift registers (one column per accepted pixel)
//   conv_mac     9 constant multipliers and an adder tree
//   conv3x3      top module: column / row counters and the valid pipeline
module conv3x3 (
    input         clk,
    input         rst,
    input         in_valid,
    input  [7:0]  in_pixel,
    output reg    out_valid,
    output [19:0] out_data
);
    localparam W = 64;

    reg  [5:0]  col;                   // column of the next pixel
    reg  [1:0]  rowc;                  // completed rows, saturating at 2
    reg  [7:0]  pix;                   // the accepted pixel (row 0 of the window column)
    reg         vA;                    // a pixel was accepted at the last edge
    reg  [3:0]  f;                     // "this pixel completes a window", one bit per pipeline stage
    wire [15:0] q;                     // {pixel of the previous row, pixel two rows back} at this column
    wire [71:0] win;

    wire full = (rowc == 2'd2) & (col >= 6'd2);

    conv_lbuf   u_lb  (.clk(clk), .en(in_valid), .addr(col), .din(in_pixel), .dout(q));
    conv_window u_win (.clk(clk), .en(vA), .c0(pix), .c1(q[15:8]), .c2(q[7:0]), .win(win));
    conv_mac    u_mac (.clk(clk), .win(win), .y(out_data));

    always @(posedge clk) begin
        if (rst) begin
            col       <= 6'd0;
            rowc      <= 2'd0;
            vA        <= 1'b0;
            f         <= 4'd0;
            out_valid <= 1'b0;
        end else begin
            vA        <= in_valid;
            f         <= {f[2:0], in_valid & full};
            out_valid <= f[3];
            if (in_valid) begin
                pix <= in_pixel;
                if (col == W - 1) begin
                    col <= 6'd0;
                    if (rowc != 2'd2) rowc <= rowc + 2'd1;
                end else begin
                    col <= col + 6'd1;
                end
            end
        end
    end
endmodule


// Line buffer: one word per column with the two previous rows. The word is read before it is overwritten:
// dout gets the old word, the memory gets {new pixel, old previous-row pixel}.
module conv_lbuf (
    input         clk,
    input         en,
    input  [5:0]  addr,
    input  [7:0]  din,
    output reg [15:0] dout
);
    reg [15:0] mem [0:63];
    wire [15:0] old = mem[addr];

    always @(posedge clk) begin
        if (en) begin
            mem[addr] <= {din, old[15:8]};
            dout      <= old;
        end
    end
endmodule


// 3x3 window: w[col*3 + row], column 0 is the newest. A new column is loaded when a pixel was accepted.
module conv_window (
    input         clk,
    input         en,
    input  [7:0]  c0,
    input  [7:0]  c1,
    input  [7:0]  c2,
    output [71:0] win
);
    reg [7:0] w [0:8];
    integer n;

    always @(posedge clk) begin
        if (en) begin
            w[0] <= c0;
            w[1] <= c1;
            w[2] <= c2;
            for (n = 3; n < 9; n = n + 1) w[n] <= w[n-3];
        end
    end

    genvar g;
    generate
        for (g = 0; g < 9; g = g + 1) begin : tap
            assign win[8*g +: 8] = w[g];
        end
    endgenerate
endmodule


// Products and adder tree, free running: edge 1 products, edge 2 sums per window column, edge 3 result.
module conv_mac (
    input         clk,
    input  [71:0] win,
    output reg [19:0] y
);
    wire signed [7:0] k [0:8];
    assign k[0] =  8'sd17;
    assign k[1] = -8'sd23;
    assign k[2] =  8'sd45;
    assign k[3] = -8'sd8;
    assign k[4] =  8'sd96;
    assign k[5] = -8'sd31;
    assign k[6] =  8'sd12;
    assign k[7] =  8'sd70;
    assign k[8] = -8'sd54;

    reg signed [16:0] m [0:8];
    reg signed [18:0] t [0:2];
    integer n;

    always @(posedge clk) begin
        for (n = 0; n < 9; n = n + 1) m[n] <= $signed({1'b0, win[8*n +: 8]}) * k[n];
        for (n = 0; n < 3; n = n + 1) t[n] <= m[3*n] + m[3*n+1] + m[3*n+2];
        y <= t[0] + t[1] + t[2];
    end
endmodule

designs.Testbench:
`timescale 1ns/1ps

// Cycle-exact testbench of conv3x3. The design under test (uut) and an untouched copy of the reference
// (refm, modules renamed ref_*) get the same stimulus; out_valid is compared every cycle and out_data in every
// cycle where the reference raises out_valid. The reference is also checked against a software 3x3 convolution.
// Runs (one frame of 6 rows x 64 pixels each, the design is reset before every run):
//   0 random pixels with gaps   1 every pixel 255, dense stream   2 random 0 / 255 pixels with gaps
module conv3x3_tb;
    localparam W    = 64;
    localparam ROWS = 6;
    localparam NP   = W * ROWS;
    localparam RUNS = 3;

    reg         clk, rst, in_valid;
    reg  [7:0]  in_pixel;
    wire        ov_d, ov_r;
    wire [19:0] od_d, od_r;

    conv3x3     uut  (.clk(clk), .rst(rst), .in_valid(in_valid), .in_pixel(in_pixel), .out_valid(ov_d), .out_data(od_d));
    ref_conv3x3 refm (.clk(clk), .rst(rst), .in_valid(in_valid), .in_pixel(in_pixel), .out_valid(ov_r), .out_data(od_r));

    initial clk = 0;
    always #5 clk = ~clk;

    // ---- software model: frame, kernel (index = column*3 + row), queue of expected results ----
    reg [7:0]        img [0:NP-1];
    reg signed [7:0] kk  [0:8];
    integer expq [0:511];
    integer qw, qr;
    integer seed, run, idx, i, dr, dc, r, c, acc, cyc, mism, shown, refbad, nvalid;

    reg cmp_on;

    task gen_frame;
        input integer mode;
        begin
            for (i = 0; i < NP; i = i + 1)
                img[i] = (mode == 1) ? 8'd255 : (mode == 2) ? (($random(seed) & 1) ? 8'd255 : 8'd0) : $random(seed);
        end
    endtask

    // Expected output when pixel idx is accepted (only pixels that complete a window produce one).
    task model_push;
        input integer pidx;
        begin
            r = pidx / W; c = pidx % W;
            if (r >= 2 && c >= 2) begin
                acc = 0;
                for (dr = 0; dr < 3; dr = dr + 1)
                    for (dc = 0; dc < 3; dc = dc + 1)
                        acc = acc + $signed({1'b0, img[(r-dr)*W + (c-dc)]}) * kk[dc*3 + dr];
                expq[qw] = acc;
                qw = qw + 1;
            end
        end
    endtask

    // ---- cycle-by-cycle comparison of the design under test with the reference copy ----
    always @(negedge clk) if (cmp_on) begin
        cyc = cyc + 1;
        if (ov_d !== ov_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | out_valid=%0d (expected %0d) | FAIL", cyc, ov_d, ov_r);
            end
        end else if (ov_r === 1'b1) begin
            nvalid = nvalid + 1;
            if (od_d !== od_r) begin
                mism = mism + 1;
                if (shown < 20) begin
                    shown = shown + 1;
                    $display(" cycle=%0d | out_data=%0d (expected %0d) | FAIL", cyc, $signed(od_d), $signed(od_r));
                end
            end
            if ($signed(od_r) !== expq[qr]) begin
                refbad = refbad + 1;
                if (refbad <= 5) $display(" reference check: y=%0d, software model %0d", $signed(od_r), expq[qr]);
            end
            qr = qr + 1;
        end
    end

    initial begin
        kk[0] =  8'sd17; kk[1] = -8'sd23; kk[2] =  8'sd45;
        kk[3] = -8'sd8;  kk[4] =  8'sd96; kk[5] = -8'sd31;
        kk[6] =  8'sd12; kk[7] =  8'sd70; kk[8] = -8'sd54;
        seed = 32'h0C0A0001; mism = 0; shown = 0; refbad = 0; cyc = 0; nvalid = 0; qw = 0; qr = 0;
        cmp_on = 0; rst = 1; in_valid = 0; in_pixel = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        repeat (24) @(posedge clk);
        #1 rst = 0;
        cmp_on = 1;
        for (run = 0; run < RUNS; run = run + 1) begin
            // reset the design and the model, then send the frame
            @(posedge clk); #1 rst = 1; in_valid = 0; in_pixel = 0;
            repeat (4) @(posedge clk);
            #1 rst = 0;
            qw = 0; qr = 0;
            gen_frame(run);
            idx = 0;
            while (idx < NP) begin
                @(posedge clk); #1;
                if (run == 1 || (($random(seed) & 3) != 0)) begin
                    in_valid = 1; in_pixel = img[idx];
                    model_push(idx);
                    idx = idx + 1;
                end else begin
                    in_valid = 0;
                end
            end
            @(posedge clk); #1 in_valid = 0;
            repeat (12) @(posedge clk);
            if (qr != qw) begin
                refbad = refbad + 1;
                $display(" run %0d: %0d outputs expected, %0d seen", run, qw, qr);
            end
            $display("run %0d: %0d pixels, %0d outputs", run, NP, qw);
        end
        #1;
        $display("-------------------------------------");
        $display("Compared %0d cycles, %0d valid outputs", cyc, nvalid);
        if (refbad != 0) $display("Reference model mismatch (%0d)", refbad);
        else if (mism == 0) $display("All tests passed");
        else $display("Some tests failed (%0d mismatching cycles)", mism);
        $display("=====================================");
        $finish;
    end
endmodule

