// Saturating dot product of two 32-element INT8 vectors, controlled by start / done.
//
//   result = saturate_12( (sum over k = 0..31 of a[k] * b[k] + 64) >>> 7 )
//
// The vectors are loaded through a write port (w_sel = 0 writes vector a, w_sel = 1 writes vector b). A run is
// started by a one-cycle start pulse while the design is idle (a start while busy is ignored). done is raised
// when the result is ready and stays high until the next accepted start.
//
// Organisation:
//   dot_buf   32 x 8 memory with a registered read, one per vector
//   dot_mac   multiplier register, then a 24-bit accumulator
//   dot_sat   rounding shift and saturation to 12 bits (combinational)
//   sat_dot32 top module: run controller and read addressing
module sat_dot32 (
    input         clk,
    input         rst,
    input         w_we,
    input         w_sel,
    input  [4:0]  w_addr,
    input  [7:0]  w_data,
    input         start,
    output reg    done,
    output reg [11:0] result
);
    localparam K = 32;                 // vector length

    reg        busy;
    reg [5:0]  cnt;                    // cycles since the start edge
    reg        v1;                     // memory output holds an element pair
    wire       go    = start & ~busy;
    wire       rd_en = busy & ~cnt[5]; // cnt < 32: the pair cnt is read at this edge

    wire [7:0]  a_q, b_q;
    wire [23:0] acc;
    wire [11:0] sat;

    dot_buf u_a   (.clk(clk), .we(w_we & ~w_sel), .waddr(w_addr), .wdata(w_data), .raddr(cnt[4:0]), .rdata(a_q));
    dot_buf u_b   (.clk(clk), .we(w_we &  w_sel), .waddr(w_addr), .wdata(w_data), .raddr(cnt[4:0]), .rdata(b_q));
    dot_mac u_mac (.clk(clk), .clr(go), .v_in(v1), .a(a_q), .b(b_q), .acc(acc));
    dot_sat u_sat (.acc(acc), .sat(sat));

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            cnt  <= 6'd0;
            v1   <= 1'b0;
        end else begin
            v1 <= rd_en;
            if (go) begin
                busy <= 1'b1;
                done <= 1'b0;
                cnt  <= 6'd0;
            end else if (busy) begin
                cnt <= cnt + 6'd1;
                // pair k reaches the accumulator at edge k + 3 (edge 0 samples start); the last one (k = 31) at
                // edge 34, so the result is captured at edge 35, the 36th edge of the run
                if (cnt == K + 2) begin
                    busy   <= 1'b0;
                    done   <= 1'b1;
                    result <= sat;
                end
            end
        end
    end
endmodule


// Vector memory: synchronous write, registered read (the read returns the old word when written at the same edge).
module dot_buf (
    input         clk,
    input         we,
    input  [4:0]  waddr,
    input  [7:0]  wdata,
    input  [4:0]  raddr,
    output reg [7:0] rdata
);
    reg [7:0] mem [0:31];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Multiply-accumulate: edge 1 registers the product, edge 2 adds it to the accumulator. clr (the start edge)
// zeroes the accumulator; the accumulator only adds products that are flagged valid.
module dot_mac (
    input         clk,
    input         clr,
    input         v_in,
    input  [7:0]  a,
    input  [7:0]  b,
    output reg signed [23:0] acc
);
    reg               v2;
    reg signed [15:0] p;

    always @(posedge clk) begin
        v2 <= v_in;
        p  <= $signed(a) * $signed(b);
        if (clr)     acc <= 24'sd0;
        else if (v2) acc <= acc + p;
    end
endmodule


// Round to nearest (add 64, arithmetic shift right by 7), then saturate to the signed 12-bit range.
module dot_sat (
    input  signed [23:0] acc,
    output [11:0]        sat
);
    wire signed [24:0] rnd = acc + 25'sd64;
    wire signed [24:0] sh  = rnd >>> 7;

    assign sat = (sh >  25'sd2047)  ? 12'h7FF :
                 (sh < -25'sd2048)  ? 12'h800 :
                                      sh[11:0];
endmodule

designs.Testbench:
`timescale 1ns/1ps

// Cycle-exact testbench of sat_dot32. The design under test (uut) and an untouched copy of the reference
// (refm, modules renamed ref_*) get the same stimulus; done is compared every cycle and result in every cycle
// where the reference raises done. The reference is also checked against a software model of the dot product.
// Runs: 0 random full-range vectors, 1 positive saturation (-128 * -128), 2 negative saturation (-128 * 127),
//       3 small values (no saturation), 4 random vectors with a second start pulse while the run is busy.
module sat_dot32_tb;
    localparam K    = 32;
    localparam RUNS = 5;

    reg         clk, rst, w_we, w_sel, start;
    reg  [4:0]  w_addr;
    reg  [7:0]  w_data;
    wire        dn_d, dn_r;
    wire [11:0] rs_d, rs_r;

    sat_dot32     uut  (.clk(clk), .rst(rst), .w_we(w_we), .w_sel(w_sel), .w_addr(w_addr), .w_data(w_data),
                        .start(start), .done(dn_d), .result(rs_d));
    ref_sat_dot32 refm (.clk(clk), .rst(rst), .w_we(w_we), .w_sel(w_sel), .w_addr(w_addr), .w_data(w_data),
                        .start(start), .done(dn_r), .result(rs_r));

    initial clk = 0;
    always #5 clk = ~clk;

    reg signed [7:0] A [0:K-1];
    reg signed [7:0] B [0:K-1];
    integer seed, run, k, since, sum, expv, cyc, mism, shown, refbad;
    reg cmp_on;

    // ---- cycle-by-cycle comparison of the design under test with the reference copy ----
    always @(negedge clk) if (cmp_on) begin
        cyc = cyc + 1;
        if (dn_d !== dn_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | done=%0d (expected %0d) | FAIL", cyc, dn_d, dn_r);
            end
        end else if (dn_r === 1'b1 && rs_d !== rs_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | result=%0d (expected %0d) | FAIL", cyc, $signed(rs_d), $signed(rs_r));
            end
        end
    end

    initial begin
        seed = 32'h0D07A001; mism = 0; shown = 0; refbad = 0; cyc = 0;
        cmp_on = 0; rst = 1; w_we = 0; w_sel = 0; w_addr = 0; w_data = 0; start = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        repeat (24) @(posedge clk);
        #1 rst = 0;
        cmp_on = 1;
        for (run = 0; run < RUNS; run = run + 1) begin
            // vectors of this run
            for (k = 0; k < K; k = k + 1) begin
                case (run)
                    1:       begin A[k] = -8'sd128; B[k] = -8'sd128; end
                    2:       begin A[k] = -8'sd128; B[k] =  8'sd127; end
                    3:       begin A[k] = ($random(seed) & 15) - 8; B[k] = ($random(seed) & 15) - 8; end
                    default: begin A[k] = $random(seed);            B[k] = $random(seed); end
                endcase
            end
            // load vector a (w_sel = 0), then vector b (w_sel = 1)
            for (k = 0; k < K; k = k + 1) begin
                @(posedge clk); #1 w_we = 1; w_sel = 0; w_addr = k; w_data = A[k];
            end
            for (k = 0; k < K; k = k + 1) begin
                @(posedge clk); #1 w_we = 1; w_sel = 1; w_addr = k; w_data = B[k];
            end
            @(posedge clk); #1 w_we = 0; w_sel = 0;
            // expected result
            sum = 0;
            for (k = 0; k < K; k = k + 1) sum = sum + A[k] * B[k];
            expv = (sum + 64) >>> 7;
            if (expv > 2047)  expv = 2047;
            if (expv < -2048) expv = -2048;
            // start pulse (the edge that samples it is the first edge of the run)
            @(posedge clk); #1 start = 1;
            @(posedge clk); #1 start = 0;
            if (run == 4) begin                       // a start while busy must be ignored
                repeat (10) @(posedge clk);
                #1 start = 1;
                @(posedge clk); #1 start = 0;
            end
            since = 0;
            while (dn_d !== 1'b1 && since < 200) begin
                @(posedge clk); #1 since = since + 1;
            end
            repeat (3) @(posedge clk);
            #1;
            if (dn_r !== 1'b1 || $signed(rs_r) !== expv) begin
                refbad = refbad + 1;
                $display(" reference check: result=%0d, software model %0d", $signed(rs_r), expv);
            end
            if (run != 4) $display("run %0d: done raised %0d cycles after start (counting the start edge)", run, since + 1);
            else          $display("run %0d: start while busy ignored", run);
        end
        #1;
        $display("-------------------------------------");
        $display("Compared %0d cycles", cyc);
        if (refbad != 0) $display("Reference model mismatch (%0d)", refbad);
        else if (mism == 0) $display("All tests passed");
        else $display("Some tests failed (%0d mismatching cycles)", mism);
        $display("=====================================");
        $finish;
    end
endmodule

// ---- untouched copy of the reference (modules renamed ref_*) ----
// Saturating dot product of two 32-element INT8 vectors, controlled by start / done.
//
//   result = saturate_12( (sum over k = 0..31 of a[k] * b[k] + 64) >>> 7 )
//
// The vectors are loaded through a write port (w_sel = 0 writes vector a, w_sel = 1 writes vector b). A run is
// started by a one-cycle start pulse while the design is idle (a start while busy is ignored). done is raised
// when the result is ready and stays high until the next accepted start.
//
// Organisation:
//   ref_dot_buf   32 x 8 memory with a registered read, one per vector
//   ref_dot_mac   multiplier register, then a 24-bit accumulator
//   ref_dot_sat   rounding shift and saturation to 12 bits (combinational)
//   ref_sat_dot32 top module: run controller and read addressing
module ref_sat_dot32 (
    input         clk,
    input         rst,
    input         w_we,
    input         w_sel,
    input  [4:0]  w_addr,
    input  [7:0]  w_data,
    input         start,
    output reg    done,
    output reg [11:0] result
);
    localparam K = 32;                 // vector length

    reg        busy;
    reg [5:0]  cnt;                    // cycles since the start edge
    reg        v1;                     // memory output holds an element pair
    wire       go    = start & ~busy;
    wire       rd_en = busy & ~cnt[5]; // cnt < 32: the pair cnt is read at this edge

    wire [7:0]  a_q, b_q;
    wire [23:0] acc;
    wire [11:0] sat;

    ref_dot_buf u_a   (.clk(clk), .we(w_we & ~w_sel), .waddr(w_addr), .wdata(w_data), .raddr(cnt[4:0]), .rdata(a_q));
    ref_dot_buf u_b   (.clk(clk), .we(w_we &  w_sel), .waddr(w_addr), .wdata(w_data), .raddr(cnt[4:0]), .rdata(b_q));
    ref_dot_mac u_mac (.clk(clk), .clr(go), .v_in(v1), .a(a_q), .b(b_q), .acc(acc));
    ref_dot_sat u_sat (.acc(acc), .sat(sat));

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            cnt  <= 6'd0;
            v1   <= 1'b0;
        end else begin
            v1 <= rd_en;
            if (go) begin
                busy <= 1'b1;
                done <= 1'b0;
                cnt  <= 6'd0;
            end else if (busy) begin
                cnt <= cnt + 6'd1;
                // pair k reaches the accumulator at edge k + 3 (edge 0 samples start); the last one (k = 31) at
                // edge 34, so the result is captured at edge 35, the 36th edge of the run
                if (cnt == K + 2) begin
                    busy   <= 1'b0;
                    done   <= 1'b1;
                    result <= sat;
                end
            end
        end
    end
endmodule


// Vector memory: synchronous write, registered read (the read returns the old word when written at the same edge).
module ref_dot_buf (
    input         clk,
    input         we,
    input  [4:0]  waddr,
    input  [7:0]  wdata,
    input  [4:0]  raddr,
    output reg [7:0] rdata
);
    reg [7:0] mem [0:31];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// Multiply-accumulate: edge 1 registers the product, edge 2 adds it to the accumulator. clr (the start edge)
// zeroes the accumulator; the accumulator only adds products that are flagged valid.
module ref_dot_mac (
    input         clk,
    input         clr,
    input         v_in,
    input  [7:0]  a,
    input  [7:0]  b,
    output reg signed [23:0] acc
);
    reg               v2;
    reg signed [15:0] p;

    always @(posedge clk) begin
        v2 <= v_in;
        p  <= $signed(a) * $signed(b);
        if (clr)     acc <= 24'sd0;
        else if (v2) acc <= acc + p;
    end
endmodule


// Round to nearest (add 64, arithmetic shift right by 7), then saturate to the signed 12-bit range.
module ref_dot_sat (
    input  signed [23:0] acc,
    output [11:0]        sat
);
    wire signed [24:0] rnd = acc + 25'sd64;
    wire signed [24:0] sh  = rnd >>> 7;

    assign sat = (sh >  25'sd2047)  ? 12'h7FF :
                 (sh < -25'sd2048)  ? 12'h800 :
                                      sh[11:0];
endmodule

designs.reference_rtl:
// Output-stationary 8x8 systolic matrix multiplier, signed INT8 operands.
// Scaled-up variant of the 4x4 design (same structure, 64 processing elements).
//
//   C[i][j] = sum over k = 0..255 of A[i][k] * B[k][j]        (i, j = 0..7)
//
// Organisation:
//   os_buf   x2   input buffers (A and B), 256 words of 64 bit, one write port and one registered read port
//   os_delay      input skew: row i of A and column j of B are delayed by i / j cycles
//   os_pe    x64  processing elements; PE(i,j) keeps C[i][j] in its accumulator
//   controller    counter that streams the buffers and raises 'done'
//   read-out      64:1 multiplexer that selects one accumulator, registered
module sa_os_8x8 (
    input         clk,
    input         rst,
    input         a_we,
    input  [7:0]  a_addr,
    input  [63:0] a_data,
    input         b_we,
    input  [7:0]  b_addr,
    input  [63:0] b_data,
    input         start,
    output reg    done,
    input  [5:0]  c_addr,
    output reg [31:0] c_data
);
    localparam K = 256;

    // ---------------------------------------------------------------- controller
    reg        busy;
    reg [8:0]  cnt;                    // cycle counter of a run
    wire       go = start & ~busy;     // a start is accepted only while idle

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (go) begin
            busy <= 1'b1;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (busy) begin
            cnt <= cnt + 9'd1;
            if (cnt == K + 15) begin   // the last product has reached PE(7,7) and been accumulated
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // ---------------------------------------------------------------- input buffers
    wire        rd_en = busy & ~cnt[8];        // cnt < 256: one word of A and of B per cycle
    wire [63:0] a_rd, b_rd;
    reg         v1;                            // the read data is valid one cycle after the address

    os_buf abuf (.clk(clk), .we(a_we), .waddr(a_addr), .wdata(a_data), .raddr(cnt[7:0]), .rdata(a_rd));
    os_buf bbuf (.clk(clk), .we(b_we), .waddr(b_addr), .wdata(b_data), .raddr(cnt[7:0]), .rdata(b_rd));

    always @(posedge clk) begin
        if (rst) v1 <= 1'b0;
        else     v1 <= rd_en;
    end

    // Outside the stream the array is fed with zeros, so the accumulators do not change.
    wire [63:0] a_g = v1 ? a_rd : 64'd0;       // byte i = A[i][k]
    wire [63:0] b_g = v1 ? b_rd : 64'd0;       // byte j = B[k][j]

    // ---------------------------------------------------------------- skew
    wire [7:0] a_s [0:7];
    wire [7:0] b_s [0:7];

    genvar i, j;
    generate
        for (i = 0; i < 8; i = i + 1) begin : skew
            if (i == 0) begin : none
                assign a_s[i] = a_g[8*i +: 8];
                assign b_s[i] = b_g[8*i +: 8];
            end else begin : delayed
                os_delay #(.W(8), .D(i)) da (.clk(clk), .din(a_g[8*i +: 8]), .dout(a_s[i]));
                os_delay #(.W(8), .D(i)) db (.clk(clk), .din(b_g[8*i +: 8]), .dout(b_s[i]));
            end
        end
    endgenerate

    // ---------------------------------------------------------------- PE array
    wire signed [7:0]  ah  [0:71];     // a operand entering PE(i,j): index i*9+j (j = 8: leaves the array)
    wire signed [7:0]  bv  [0:71];     // b operand entering PE(i,j): index i*8+j (i = 8: leaves the array)
    wire signed [31:0] acc_w [0:63];   // accumulator of PE(i,j): index i*8+j

    generate
        for (i = 0; i < 8; i = i + 1) begin : row
            assign ah[i*9] = a_s[i];
            for (j = 0; j < 8; j = j + 1) begin : col
                if (i == 0) begin : top
                    assign bv[j] = b_s[j];
                end
                os_pe pe (
                    .clk(clk), .rst(rst), .clr(go),
                    .a_in(ah[i*9+j]),     .b_in(bv[i*8+j]),
                    .a_out(ah[i*9+j+1]),  .b_out(bv[(i+1)*8+j]),
                    .acc(acc_w[i*8+j])
                );
            end
        end
    endgenerate

    // ---------------------------------------------------------------- read-out
    always @(posedge clk) c_data <= acc_w[c_addr];
endmodule


// Input buffer: simple dual-port memory, synchronous write, registered read.
module os_buf (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [63:0] wdata,
    input  [7:0]  raddr,
    output reg [63:0] rdata
);
    reg [63:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// D-cycle delay line of a W-bit signal (D >= 1).
module os_delay #(parameter W = 8, parameter D = 1) (
    input          clk,
    input  [W-1:0] din,
    output [W-1:0] dout
);
    reg [W-1:0] sh [0:D-1];
    integer n;

    always @(posedge clk) begin
        sh[0] <= din;
        for (n = 1; n < D; n = n + 1) sh[n] <= sh[n-1];
    end
    assign dout = sh[D-1];
endmodule


// Processing element: passes both operands on (one register each) and accumulates the products.
module os_pe (
    input                     clk,
    input                     rst,
    input                     clr,      // clears the accumulator at the start of a run
    input  signed [7:0]       a_in,
    input  signed [7:0]       b_in,
    output reg signed [7:0]   a_out,
    output reg signed [7:0]   b_out,
    output reg signed [31:0]  acc
);
    reg signed [15:0] prod;

    always @(posedge clk) begin
        a_out <= a_in;
        b_out <= b_in;
        prod  <= a_in * b_in;
    end

    always @(posedge clk or posedge rst) begin
        if (rst)      acc <= 32'sd0;
        else if (clr) acc <= 32'sd0;
        else          acc <= acc + prod;
    end
endmodule

designs.Testbench:
`timescale 1ns/1ps

// Cycle-exact testbench of sa_os_8x8. The design under test (uut) and an untouched copy of the reference
// (refm, modules renamed ref_*) get the same stimulus; 'done' is compared every cycle and 'c_data' while
// the result is read out. The reference is also checked against a software matrix product.
module sa_os_8x8_tb;
    localparam K    = 256;
    localparam NOUT = 64;
    localparam RUNS = 3;

    reg         clk;
    reg         rst, start, a_we, b_we;
    reg  [7:0]  a_addr, b_addr;
    reg  [63:0] a_data, b_data;
    reg  [5:0]  c_addr;
    wire        done_d, done_r;
    wire [31:0] cd_d, cd_r;

    sa_os_8x8 uut (.clk(clk), .rst(rst), .a_we(a_we), .a_addr(a_addr), .a_data(a_data),
                   .b_we(b_we), .b_addr(b_addr), .b_data(b_data), .start(start), .done(done_d),
                   .c_addr(c_addr), .c_data(cd_d));
    ref_sa_os_8x8 refm (.clk(clk), .rst(rst), .a_we(a_we), .a_addr(a_addr), .a_data(a_data),
                        .b_we(b_we), .b_addr(b_addr), .b_data(b_data), .start(start), .done(done_r),
                        .c_addr(c_addr), .c_data(cd_r));

    initial clk = 0;
    always #5 clk = ~clk;

    // ---- software model: A[i*K+k], B[k*8+j], expc[i*8+j] ----
    reg signed [7:0] A [0:8*K-1];
    reg signed [7:0] B [0:8*K-1];
    integer expc [0:NOUT-1];
    integer seed, run, k, i, j, a, guard, since, mism, shown, refbad, cyc;
    reg cmp_on, cmp_c;

    task gen;
        input integer mode;                       // 0, 2: random; 1: every operand -128 (largest sums)
        begin
            for (k = 0; k < 8*K; k = k + 1) begin
                A[k] = (mode == 1) ? -8'sd128 : $random(seed);
                B[k] = (mode == 1) ? -8'sd128 : $random(seed);
            end
            for (i = 0; i < 8; i = i + 1)
                for (j = 0; j < 8; j = j + 1) begin
                    expc[i*8+j] = 0;
                    for (k = 0; k < K; k = k + 1)
                        expc[i*8+j] = expc[i*8+j] + A[i*K+k] * B[k*8+j];
                end
        end
    endtask

    // ---- cycle-by-cycle comparison of the design under test with the reference copy ----
    always @(negedge clk) if (cmp_on) begin
        cyc = cyc + 1;
        if (done_d !== done_r) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | done=%0d (expected %0d) | FAIL", cyc, done_d, done_r);
            end
        end
        if (cmp_c && (cd_d !== cd_r)) begin
            mism = mism + 1;
            if (shown < 20) begin
                shown = shown + 1;
                $display(" cycle=%0d | c_data=%0d (expected %0d) | FAIL", cyc, $signed(cd_d), $signed(cd_r));
            end
        end
    end

    initial begin
        seed = 32'h05A80001; mism = 0; shown = 0; refbad = 0; cyc = 0;
        cmp_on = 0; cmp_c = 0;
        rst = 1; start = 0; a_we = 0; b_we = 0; a_addr = 0; b_addr = 0; a_data = 0; b_data = 0; c_addr = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        repeat (24) @(posedge clk);
        #1 rst = 0;
        cmp_on = 1;
        for (run = 0; run < RUNS; run = run + 1) begin
            gen((run == 1) ? 1 : 0);
            // load both buffers, one word per cycle: byte i of an A word is A[i][k], byte j of a B word is B[k][j]
            for (k = 0; k < K; k = k + 1) begin
                @(posedge clk); #1;
                for (i = 0; i < 8; i = i + 1) begin
                    a_data[8*i +: 8] = A[i*K+k];
                    b_data[8*i +: 8] = B[k*8+i];
                end
                a_we = 1; a_addr = k;
                b_we = 1; b_addr = k;
            end
            @(posedge clk); #1; a_we = 0; b_we = 0;
            repeat (3) @(posedge clk);
            #1 start = 1;
            @(posedge clk); #1 start = 0;
            // wait for done
            guard = 0; since = 0;
            while (done_d !== 1'b1 && guard < 1000) begin
                @(posedge clk); #1; guard = guard + 1; since = since + 1;
            end
            $display("run %0d: done raised %0d cycles after the start edge", run, since + 1);
            // read out: c_addr is sampled at an edge, c_data is valid right after the next edge
            cmp_c = 1;
            for (a = 0; a <= NOUT; a = a + 1) begin
                @(posedge clk); #1;
                if (a > 0 && $signed(cd_r) !== expc[a-1]) begin
                    refbad = refbad + 1;
                    if (refbad <= 5) $display(" reference check: C[%0d] = %0d, software model %0d", a-1, $signed(cd_r), expc[a-1]);
                end
                c_addr = (a < NOUT) ? a : 0;
            end
            cmp_c = 0;
            repeat (4) @(posedge clk);
        end
        #1;
        $display("-------------------------------------");
        $display("Compared %0d cycles", cyc);
        if (refbad != 0) $display("Reference model mismatch (%0d)", refbad);
        else if (mism == 0) $display("All tests passed");
        else $display("Some tests failed (%0d mismatching cycles)", mism);
        $display("=====================================");
        $finish;
    end
endmodule

// ---- untouched copy of the reference (modules renamed ref_*) ----
// Output-stationary 8x8 systolic matrix multiplier, signed INT8 operands.
// Scaled-up variant of the 4x4 design (same structure, 64 processing elements).
//
//   C[i][j] = sum over k = 0..255 of A[i][k] * B[k][j]        (i, j = 0..7)
//
// Organisation:
//   ref_os_buf   x2   input buffers (A and B), 256 words of 64 bit, one write port and one registered read port
//   ref_os_delay      input skew: row i of A and column j of B are delayed by i / j cycles
//   ref_os_pe    x64  processing elements; PE(i,j) keeps C[i][j] in its accumulator
//   controller    counter that streams the buffers and raises 'done'
//   read-out      64:1 multiplexer that selects one accumulator, registered
module ref_sa_os_8x8 (
    input         clk,
    input         rst,
    input         a_we,
    input  [7:0]  a_addr,
    input  [63:0] a_data,
    input         b_we,
    input  [7:0]  b_addr,
    input  [63:0] b_data,
    input         start,
    output reg    done,
    input  [5:0]  c_addr,
    output reg [31:0] c_data
);
    localparam K = 256;

    // ---------------------------------------------------------------- controller
    reg        busy;
    reg [8:0]  cnt;                    // cycle counter of a run
    wire       go = start & ~busy;     // a start is accepted only while idle

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (go) begin
            busy <= 1'b1;
            done <= 1'b0;
            cnt  <= 9'd0;
        end else if (busy) begin
            cnt <= cnt + 9'd1;
            if (cnt == K + 15) begin   // the last product has reached PE(7,7) and been accumulated
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // ---------------------------------------------------------------- input buffers
    wire        rd_en = busy & ~cnt[8];        // cnt < 256: one word of A and of B per cycle
    wire [63:0] a_rd, b_rd;
    reg         v1;                            // the read data is valid one cycle after the address

    ref_os_buf abuf (.clk(clk), .we(a_we), .waddr(a_addr), .wdata(a_data), .raddr(cnt[7:0]), .rdata(a_rd));
    ref_os_buf bbuf (.clk(clk), .we(b_we), .waddr(b_addr), .wdata(b_data), .raddr(cnt[7:0]), .rdata(b_rd));

    always @(posedge clk) begin
        if (rst) v1 <= 1'b0;
        else     v1 <= rd_en;
    end

    // Outside the stream the array is fed with zeros, so the accumulators do not change.
    wire [63:0] a_g = v1 ? a_rd : 64'd0;       // byte i = A[i][k]
    wire [63:0] b_g = v1 ? b_rd : 64'd0;       // byte j = B[k][j]

    // ---------------------------------------------------------------- skew
    wire [7:0] a_s [0:7];
    wire [7:0] b_s [0:7];

    genvar i, j;
    generate
        for (i = 0; i < 8; i = i + 1) begin : skew
            if (i == 0) begin : none
                assign a_s[i] = a_g[8*i +: 8];
                assign b_s[i] = b_g[8*i +: 8];
            end else begin : delayed
                ref_os_delay #(.W(8), .D(i)) da (.clk(clk), .din(a_g[8*i +: 8]), .dout(a_s[i]));
                ref_os_delay #(.W(8), .D(i)) db (.clk(clk), .din(b_g[8*i +: 8]), .dout(b_s[i]));
            end
        end
    endgenerate

    // ---------------------------------------------------------------- PE array
    wire signed [7:0]  ah  [0:71];     // a operand entering PE(i,j): index i*9+j (j = 8: leaves the array)
    wire signed [7:0]  bv  [0:71];     // b operand entering PE(i,j): index i*8+j (i = 8: leaves the array)
    wire signed [31:0] acc_w [0:63];   // accumulator of PE(i,j): index i*8+j

    generate
        for (i = 0; i < 8; i = i + 1) begin : row
            assign ah[i*9] = a_s[i];
            for (j = 0; j < 8; j = j + 1) begin : col
                if (i == 0) begin : top
                    assign bv[j] = b_s[j];
                end
                ref_os_pe pe (
                    .clk(clk), .rst(rst), .clr(go),
                    .a_in(ah[i*9+j]),     .b_in(bv[i*8+j]),
                    .a_out(ah[i*9+j+1]),  .b_out(bv[(i+1)*8+j]),
                    .acc(acc_w[i*8+j])
                );
            end
        end
    endgenerate

    // ---------------------------------------------------------------- read-out
    always @(posedge clk) c_data <= acc_w[c_addr];
endmodule


// Input buffer: simple dual-port memory, synchronous write, registered read.
module ref_os_buf (
    input         clk,
    input         we,
    input  [7:0]  waddr,
    input  [63:0] wdata,
    input  [7:0]  raddr,
    output reg [63:0] rdata
);
    reg [63:0] mem [0:255];

    always @(posedge clk) begin
        if (we) mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end
endmodule


// D-cycle delay line of a W-bit signal (D >= 1).
module ref_os_delay #(parameter W = 8, parameter D = 1) (
    input          clk,
    input  [W-1:0] din,
    output [W-1:0] dout
);
    reg [W-1:0] sh [0:D-1];
    integer n;

    always @(posedge clk) begin
        sh[0] <= din;
        for (n = 1; n < D; n = n + 1) sh[n] <= sh[n-1];
    end
    assign dout = sh[D-1];
endmodule


// Processing element: passes both operands on (one register each) and accumulates the products.
module ref_os_pe (
    input                     clk,
    input                     rst,
    input                     clr,      // clears the accumulator at the start of a run
    input  signed [7:0]       a_in,
    input  signed [7:0]       b_in,
    output reg signed [7:0]   a_out,
    output reg signed [7:0]   b_out,
    output reg signed [31:0]  acc
);
    reg signed [15:0] prod;

    always @(posedge clk) begin
        a_out <= a_in;
        b_out <= b_in;
        prod  <= a_in * b_in;
    end

    always @(posedge clk or posedge rst) begin
        if (rst)      acc <= 32'sd0;
        else if (clr) acc <= 32'sd0;
        else          acc <= acc + prod;
    end
endmodule
